<script src="https://cdn.plot.ly/plotly-3.1.0.min.js"></script>
<script>
const data = {
  title: "Bản đồ phân bố: Meliaceae",
  iso3_codes: ['BDI', 'MOZ', 'COG', 'MWI', 'TZA', 'CMR', 'UGA', 'KEN', 'ZMB'],
  color: [1, 1, 1, 1, 1, 1, 1, 1, 1]
};
const trace = {
  type: "choropleth",
  locationmode: "ISO-3",
  locations: data.iso3_codes,
  z: data.color,
  colorscale: [[0, "#EAEAEA"], [1, "#FFB6C1"]],
  zmin: 0,
  zmax: 1,
  showscale: false
};
const layout = {
  title: {
    text: data.title,
    font: { size: 20 }
  },
  geo: {
    projection: { type: "natural earth" },
    showland: true,
    landcolor: "#EAEAEA",
    showcountries: true
  },
  margin: { l: 0, r: 0, t: 40, b: 0 }
};
Plotly.newPlot("map-leo", [trace], layout);
</script>



